# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KUR\'AN\'DAN DUALAR ÖĞRENİYORUM: A\'RÂF SURESİ 151. AYET</text>\n  <rect x="25" y="46" width="650" height="82" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="76" text-anchor="middle" font-size="17" font-weight="bold" fill="#92400e">قَالَ رَبِّ اغْفِرْ لِي وَلِأَخِي وَأَدْخِلْنَا فِي رَحْمَتِكَ ۖ وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ</text>\n  <text x="350" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">"(Musa:) Ey Rabbim! Beni ve kardeşimi bağışla, bizi rahmetine kabul et.</text>\n  <text x="350" y="118" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">Sen merhametlilerin en merhametlisisin, dedi." (A\'râf Suresi, 151. Ayet)</text>\n  <rect x="25" y="138" width="315" height="104" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="160" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Ayetin İndiriliş Bağlamı (Kıssa)</text>\n  <text x="40" y="182" font-size="11" fill="#1e3a8a">• Hz. Musa, Tûr Dağı\'ndan döndüğünde kavminin</text>\n  <text x="48" y="198" font-size="11" fill="#1e3a8a">Sâmirî\'nin yaptığı buzağı heykeline taptığını görür.</text>\n  <text x="40" y="218" font-size="11" fill="#1e3a8a">• Kardeşi Hz. Harun\'u dinledikten sonra sakinleşir</text>\n  <text x="48" y="232" font-size="11" fill="#1e3a8a">ve hem kendisi hem kardeşi için bu duayı yapar.</text>\n  <rect x="360" y="138" width="315" height="104" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="160" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">Duadaki Temel Kavramlar</text>\n  <text x="376" y="182" font-size="11" fill="#14532d">• <tspan font-weight="bold">Rabbiğfirlî (رَبِّ اغْفِرْ لِي):</tspan> Rabbim beni bağışla</text>\n  <text x="376" y="202" font-size="11" fill="#14532d">• <tspan font-weight="bold">Ve li-ehî (وَلِأَخِي):</tspan> Ve kardeşimi de (bağışla)</text>\n  <text x="376" y="222" font-size="11" fill="#14532d">• <tspan font-weight="bold">Erhamü\'r-râhimîn (أَرْحَمُ الرَّاحِمِينَ):</tspan> Merhametlilerin</text>\n  <text x="386" y="236" font-size="11" fill="#14532d">en merhametlisi (Allah\'ın sonsuz rahmeti)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM\'DA DUANIN ÖNEMİ VE KUR\'AN DUALARININ REHBERLİĞİ</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Kur\'an\'da Dua Adabı ve İlkeleri</text>\n  <text x="42" y="96" font-size="11.5" fill="#1e3a8a">1. <tspan font-weight="bold">İhlas ve Tevazu:</tspan> Gösterişten uzak, gizlice</text>\n  <text x="54" y="112" font-size="11" fill="#1e3a8a">ve yalvararak (tazarru ile) dua etmek (A\'râf, 55).</text>\n  <text x="42" y="136" font-size="11.5" fill="#1e3a8a">2. <tspan font-weight="bold">Korku ve Ümit (Havf ve Recâ):</tspan> Azabından</text>\n  <text x="54" y="152" font-size="11" fill="#1e3a8a">korkup rahmetinden ümit kesmeden yönelmek.</text>\n  <text x="42" y="176" font-size="11.5" fill="#1e3a8a">3. <tspan font-weight="bold">Kardeşlik Bilinci:</tspan> Yalnız kendisi için değil,</text>\n  <text x="54" y="192" font-size="11" fill="#1e3a8a">anne-babası ve mümin kardeşleri için dua etmek.</text>\n  <rect x="42" y="202" width="280" height="28" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Esma-i Hüsna (En Güzel İsimler) ile dua</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">Kur\'an\'daki Diğer Örnek Peygamber Duaları</text>\n  <rect x="378" y="84" width="280" height="44" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="388" y="101" font-size="11" font-weight="bold" fill="#7e22ce">Hz. Âdem ve Hz. Havva (A\'râf, 23):</text>\n  <text x="388" y="117" font-size="10.5" fill="#581c87">"Rabbimiz! Biz kendimize zulmettik, bizi bağışla..."</text>\n  <rect x="378" y="136" width="280" height="44" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="388" y="153" font-size="11" font-weight="bold" fill="#7e22ce">Hz. İbrahim (İbrâhîm, 40-41):</text>\n  <text x="388" y="169" font-size="10.5" fill="#581c87">"Rabbim! Beni, soyumu namaz kılanlardan eyle..."</text>\n  <rect x="378" y="188" width="280" height="44" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="388" y="205" font-size="11" font-weight="bold" fill="#7e22ce">Rabbenâ Duaları (Bakara, 201):</text>\n  <text x="388" y="221" font-size="10.5" fill="#581c87">"Rabbimiz! Bize dünyada da ahirette de iyilik ver..."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">1. ÜNİTE GENEL ÖZETİ: KUR\'AN-I KERİM\'İ TANIYALIM</text>\n  <rect x="22" y="48" width="210" height="192" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. Kur\'an Tarihi ve Özellikleri</text>\n  <text x="34" y="94" font-size="10.5" fill="#1e3a8a">• 610 (Kadir Gecesi) - 632 (23 yıl)</text>\n  <text x="34" y="114" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Hz. Ebû Bekir:</tspan> Mushaf haline</text>\n  <text x="42" y="128" font-size="10.5" fill="#1e3a8a">getirilmesi (Cem\'u\'l-Kur\'an)</text>\n  <text x="34" y="148" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Hz. Osman:</tspan> Çoğaltılması (İstinsah)</text>\n  <text x="34" y="168" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Ana Konular:</tspan> İnanç (İtikat),</text>\n  <text x="42" y="182" font-size="10.5" fill="#1e3a8a">İbadet, Ahlak, Muamelat, Kıssalar</text>\n  <rect x="34" y="196" width="186" height="32" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="127" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Furkan, Şifa, Nur, Hüda, Zikir</text>\n  <rect x="245" y="48" width="210" height="192" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">2. Mülk ve Nebe Sureleri</text>\n  <text x="257" y="94" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Mülk Suresi (30 ayet, Mekki):</tspan></text>\n  <text x="265" y="108" font-size="10.5" fill="#14532d">29. cüzün ilk suresi (Tebâreke).</text>\n  <text x="265" y="122" font-size="10.5" fill="#14532d">İlahi hükümranlık, ölüm ve hayat</text>\n  <text x="265" y="136" font-size="10.5" fill="#14532d">imtihanı, kâinattaki eşsiz düzen.</text>\n  <text x="257" y="158" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Nebe Suresi (40 ayet, Mekki):</tspan></text>\n  <text x="265" y="172" font-size="10.5" fill="#14532d">30. cüzün ilk suresi (Amme).</text>\n  <text x="265" y="186" font-size="10.5" fill="#14532d">Büyük haber (Kıyamet ve diriliş).</text>\n  <rect x="257" y="196" width="186" height="32" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="350" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Ahiret bilinci ve hesap sorumluluğu</text>\n  <rect x="468" y="48" width="210" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="573" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">3. Dua Bilinci (A\'râf, 151)</text>\n  <text x="480" y="96" font-size="10.5" fill="#78350f">• Kulun acziyetini bilip Rabb\'ine</text>\n  <text x="488" y="110" font-size="10.5" fill="#78350f">sığınması ("İbadetin özü").</text>\n  <text x="480" y="132" font-size="10.5" fill="#78350f">• Hz. Musa\'nın kendisi ve kardeşi</text>\n  <text x="488" y="146" font-size="10.5" fill="#78350f">Hz. Harun için mağfiret duası.</text>\n  <text x="480" y="168" font-size="10.5" fill="#78350f">• Öfke anında bile adaleti ve</text>\n  <text x="488" y="182" font-size="10.5" fill="#78350f">kardeşlik hukukunu korumak.</text>\n  <rect x="480" y="196" width="186" height="32" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="573" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Mağfiret + İlahi Rahmet talebi</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
